import assert from'node:assert/strict';import type{GeneratedBody}from'../../src/core/generators/definition';import{legacy2018AutumnLteReview as r}from'./legacy-2018-autumn-lte-review';
export function legacy2018AutumnLteOracle(b:GeneratedBody,v:number[]){assert.equal(v.length,3);assert(v.every(n=>n===0||n===1));assert.equal(b.prompt.length,2);assert.deepEqual(b.prompt[0],{type:'paragraph',text:r.prompt});assert.deepEqual(b.prompt[1],{type:'list',ordered:true,items:r.features});assert.equal(b.choices.length,4);const actual=b.choices.map(bs=>{assert.equal(bs.length,1);assert.equal(bs[0].type,'paragraph');return(bs[0]as{type:'paragraph';text:string}).text;}),expected=[r.correct.label,...r.axes.map((a,i)=>a[v[i]].label)];assert.deepEqual(actual,expected);const facts=new Map<string,{mobileSystem:boolean}>([[r.correct.label,r.correct],...r.axes.flatMap(a=>a.map(f=>[f.label,f]as[string,typeof f]))]),truth=actual.map(label=>{const f=facts.get(label);assert(f);return f.mobileSystem;});assert.equal(truth.filter(Boolean).length,1);assert.equal(b.correctIndex,truth.indexOf(true));assert(r.correct.packet&&r.correct.mimoAvailable&&r.correct.standardizer==='3GPP');for(const term of['パケット交換','複数アンテナ','3GPPで標準化',...r.axes.flatMap((a,i)=>a[v[i]].explanation)])assert(b.explanation.includes(term));assert(!/[アイウエ]が正答|IEEE専用|規格本文を転載/.test(b.explanation));return truth;}
